const items = $input.all();
const webhookData = $('Webhook - Template Request').item.json.body;
const variables = webhookData.variables || {};
const recipientEmail = webhookData.email;
const recipientName = webhookData.name || '';

if (items.length === 0) {
  return [{ json: { error: 'Template not found', template_id: webhookData.template_id } }];
}

const template = items[0].json;
let subject = template.subject || 'No Subject';
let body = template.body || '';

// Replace all {{variable}} placeholders
const allVars = { name: recipientName, email: recipientEmail, ...variables };
for (const [key, value] of Object.entries(allVars)) {
  const regex = new RegExp(`\\{\\{\\s*${key}\\s*\\}\\}`, 'gi');
  subject = subject.replace(regex, value);
  body = body.replace(regex, value);
}

// Replace any remaining unreplaced variables with empty
subject = subject.replace(/\{\{\s*\w+\s*\}\}/g, '');
body = body.replace(/\{\{\s*\w+\s*\}\}/g, '');

return [{
  json: {
    to: recipientEmail,
    subject: subject,
    body: body,
    template_id: webhookData.template_id,
    template_name: template.template_name || '',
    sentAt: new Date().toISOString()
  }
}];
